def prepare():
    lang=materialize();delta=read(PROJECT/'lexical-delta.json');added=[]
    def add(key,e,gloss):
        if key in delta['entries']:return
        assert key not in lang.lexicon,key
        scope = 'editorial-exception' if key in {'stanza_misnamed', 'mock_invocation', 'scrippage_play', 'phoebe_address'} else 'later-literary' if key in {'mortal_intensive', 'burden_refrain', 'perish_literary'} else 'later-standard'
        e.update(semanticId='lex.'+key,usageScope=scope,status='authored',historicalForms=[])
        delta['entries'][key]=e;delta['glosses'][key]=gloss;added.append(key)
    for key,(parent,gloss,pos,meaning) in CONTEXTS.items():
        e=deepcopy(lang.lexicon[parent]);e.update(pos=pos,meaning=meaning,origin='Reviewed contextual sense of '+parent)
        if key=='athlete_player':
            e['form']=lang.lexicon['game']['form']+lang.lexicon['person']['form']
            e['roman']=lang.reading(e['form'])
            e['origin']='Native game + person; authored contextual derivation.'
            e['derivationKeys']=['game','person']
        if key=='cradle_baby':
            e['form']=lang.lexicon['baby_infant']['form']+lang.lexicon['bed']['form']
            e['roman']=lang.reading(e['form'])
            e['origin']='Native infant + bed; authored source-category compound.'
            e['derivationKeys']=['baby_infant','bed']
        compounds={'arm_sling':['arm','hang'],'estate_settle':['land','right','give'],'giddy_haste':['head','turn'],
                   'middling_so':['so','so'],'rhetorical_figure':['speech','image'],'bastinado_beating':['stick','beat'],'perish_literary':['life','cease'],
                   'forest_purlieu':['forest','edge'],'moss_growth':['soft','green','cover'],
                   'udder_animal':['milk','breast'],'lioness_animal':['female','lion'],'chew_food':['mouth','crush'],
                   'freestone_building':['cut','stone'],'phoebe_address':['phoebe_shepherdess','act'],
                   'parrot_native':['speech','bird'],'hyena_native':['bone','tooth'],
                   'novelty_fond':['new','desire'],'keyhole_opening':['key','hole'],
                   'casement_window':['turn','window'],'thought_brooding':['thought','sorrow'],
                   'wooden_post':['wood','stand'],'musician_person':['music','person'],
                   'lisp_speech':['tongue','soft'],'gondola_boat':['city','boat'],
                   'jointure_widow':['widow','right'],'clap_touch':['hand','beat'],
                   'clothing_pin':['needle','bind'],'bugle_bead':['glass','small','round'],
                   'cream_milk':['milk','top'],
                   'chestnut_colour':['kjv_chestnut','colour'],'joust_tilt':['horse','spear','fight'],
                   'precocious_child':['early','know'],'slovenly_woman':['dirty','woman'],
                   'slovenliness':['dirty','manner'],
                   'thatch_roof':['straw','roof'],'sugar_native':['reed','sweet'],
                   'parish_vicar':['community','priest'],'chapel_worship':['small','faith','house'],
                   'wood_panelling':['wood','wall'],'wood_panel':['wood','piece'],
                   'coin_currency':['metal','money'],
                   'ode_lyric':['praise','song'],'elegy_lament':['sorrow','song'],
                   'quotidian_fever':['day','fever'],'garment_button':['round','bind'],
                   'monastic_secluded':['faith','alone'],
                   'goldsmith_craft':['gold','work','person'],
                   'footservant_lackey':['foot','servant'],'amble_gait':['smooth','step'],
                   'legal_term':['law','time'],'legal_recess':['law','rest'],
                   'catechism_teaching':['faith','teach'],
                   'supper_evening':['evening','food'],'line_clothing':['inside','cloth'],
                   'gallop_gait':['horse','run'],'medlar_fruit':['fruit','soft'],
                   'parishioner_member':['faith','person'],'scrippage_play':['carry','bag','thing'],
                   'rat_native':['corn','tooth'],'complexion_colour':['face','colour'],
                   'cork_stop':['wood','close'],
                   'legal_extent':['value','seize'],'philosophy_inquiry':['cause','know'],
                   'sparing_plain':['little','means'],'ewe_sheep':['female','sheep'],
                   'ram_sheep':['native_male','sheep'],'wether_sheep':['cut','sheep'],
                   'civet_perfume':['cat','odour'],'animal_copulation':['body','join'],
                   'herd_livestock':['herd','beast'],
                   'doe_deer':['female','deer'],'fawn_deer':['young','deer'],
                   'theatre_space':['play','house'],'mewl_infant':['weak','call'],
                   'satchel_bag':['school','bag'],'eyebrow_hair':['brow','hair'],
                   'spotted_cat_native':['spot','cat'],'capon_fowl':['cut','cock_fowl'],
                   'stock_old_man':['old','mask'],'slipper_shoe':['soft','shoe'],
                   'spectacles_sight':['sight','glass'],'treble_voice':['high','voice'],
                   'holly_native':['thorn','leaf'],'ingratitude_native':['not','gratitude'],
                   'natural_fool':['nature','fool'],'whetstone_edge':['whet','stone'],
                   'mustard_condiment':['sharp','seed','sauce'],'trowel_masonry':['wall','spread','blade'],
                   'interrupt_speech':['off','cut'],'adopt_heir':['choose','heir'],
                   'quintain_practice':['exercise','target'],'capricious_temper':['change','will'],
                   'burr_clinging':['thorn','seed'],'working_day':['work','day'],
                   'holiday_rest':['rest','day'],'umber_pigment':['brown','earth'],
                   'curtalax_sword':['short','sword'],'ducal_territory':['duke','land'],
                   'sermon_teaching':['teach','speech'],'forked_arrowhead':['branch','arrow','head'],
                   'stag_deer':['native_male','deer'],'sparrow_bird':['seed','bird'],
                   'advancement_rank':['rank','rise'],'doublet_garment':['body','garment'],
                   'cross_mark':['cross','mark'],'laundry_batler':['wash','wood','beat'],
                   'animal_teat':['milk','breast'],'pea_pod_native':['round','seed','cover'],
                   'pod_shell':['seed','cover'],'shin_body':['leg','bone'],
                   'cottage_house':['small','house'],'sheepcote_shelter':['sheep','house'],
                   'shear_fleece':['sheep','hair','cut'],'pastoral_feeder':['feed','person'],
                   'stanza_song':['song','group'],'dog_ape_native':['dog','monkey'],
                   'motley_cloth':['mixed','colour','cloth'],'lung_organ':['breath','chamber'],
                   'dissect_examine':['cut','look'],'reckoning_counter':['reckon','token'],
                   'libertine_person':['lust','liberty','person'],'finery_clothing':['adorn','garment'],
                   'church_building_native':['faith','house'],'wild_goose_native':['neck','water','bird']}
        if key in compounds:
            e['derivationKeys']=compounds[key]
            e['form']=''.join(lang.lexicon[x]['form'] for x in compounds[key])
            e['roman']=lang.reading(e['form']);e['origin']='Authored native compound: '+' + '.join(compounds[key])
        if key=='stanza_misnamed':
            e.update(form='lilgrur', roman='lilgrur', derivationKeys=['song','group'], origin='Authored local distortion of native lilgur; source naming joke.')
        if key=='mock_invocation':
            form=lang.lexicon['come']['form']+'fen'
            e.update(form=form, roman=lang.reading(form), derivationKeys=['come','fool','circle'], origin='Authored nonce blend: come + clipped/reordered fool and circle; not claimed Greek or a historical form.')
        if key=='both_pair':
            e.update(numericValue='2',numericNotation='words',numericKind='cardinal',derivationKeys=['two','all'])
        if key in {'friday_source','saturday_source'}:
            from tools.unta_language import quantity
            ordinal={'friday_source':6,'saturday_source':7}[key]
            form=quantity(ordinal,'ordinal')['form']+' '+lang.lexicon['day']['form']
            e.update(form=form,roman=lang.reading(form),derivationKeys=['six' if ordinal==6 else 'seven','day'],
                     sourceCalendar='English seven-day week, Sunday-first naming convention',
                     sourceWeekdayOrdinal=ordinal,origin='Authored source-calendar label: Unta spoken ordinal plus day; not a native-calendar equivalence.')
        add(key,e,gloss)
    for key,(form,gloss,meaning) in NAMES.items():
        add(key,dict(form=form,roman=lang.reading(form),pos='proper',meaning=meaning,
                    origin='Author-permitted phonetic adaptation of a personal name.'),gloss)
    if added:
        delta['decisions'].append(dict(work='as-you-like-it',decision=
            'Keep the brothers, servant and wrestler distinct from namesakes. Preserve source figures versus words in Unta; ordinal first-born differs from relative eldest, and thrice a villain is threefold intensity.'))
    write(PROJECT/'lexical-delta.json',delta);materialize()
    print('As You Like It lexical additions:',len(added))

if __name__=='__main__':prepare()
